CSpell::CSpell() : CWeaponObject(0)
{
	m_Node = LoadColladaScene("Scenes/Spells/spell_shield.bdae");
	__IRR_SCENE()->getRootSceneNode()->addChild(m_Node);
	cleanNode(m_Node);
	setEmissiveColor(m_Node, CGameConfig::EmissiveColorForInteractiveObjects * 0.5f);
	m_shield.setRoot(m_Node);

	m_touch = 0;

	m_behaviour = 0;

	setLevel(ST_None);
	reset();

	m_fingerTrailTexture = __IRR_DRIVER()->getTexture("Scenes/Spells/finger_trail.png");
	m_fingerTrailTexture->grab();
}

void CSpell::reset()
{
	CWeaponObject::reset();

	/// patch to reload spell behaviors
	setLevel(m_level);

	if (m_level == ST_None)
	{
		setState(SS_Disabled);
	}
	else
	{
		setState(SS_Ready);
	}

	m_cooldown = 0.0f;

	setVisible(true);
}

CSpell::~CSpell()
{
	m_Node->remove();
	m_Node->drop();

	m_fingerTrailTexture->drop();

	SAFE_DEL(m_behaviour);
}

void CSpell::adjustStats(IAttributes* attributes)
{
	const char* cooldown[] = { "CooldownEasy", "CooldownMedium", "CooldownHard" };
	int difficulty = (int)(CPlayfield::GetInstance()->getDifficulty());
	m_stat_cooldown =	attributes->getAttributeAsFloat( cooldown[difficulty] );

	if (CGameConfig::NoWeaponCD) m_stat_cooldown = 0.5f;

	SAFE_DEL(m_behaviour);
	ITexture * tex = 0;
	switch (m_level)
	{
	case ST_Boulder:
		{
			tex = __IRR_DRIVER()->getTexture("Scenes/Spells/shield_boulder.png");
			m_behaviour = new CBoulderBehaviour;
		}
		break;

	case ST_Lightning:
		{
			tex = __IRR_DRIVER()->getTexture("Scenes/Spells/shield_lightning.png");
			m_behaviour = new CLightningBehaviour;
			break;
		}

		case ST_Tornado:
		{
			tex = __IRR_DRIVER()->getTexture("Scenes/Spells/shield_tornado.png");
			m_behaviour = new CTornadoBehaviour;
			break;
		}

		case ST_GhostArmy:
		{
			tex = __IRR_DRIVER()->getTexture("Scenes/Spells/shield_ghost_army.png");
			m_behaviour = new CGhostArmyBehaviour;
			break;
		}
	}

	m_shield.getRoot()->getSceneNodeFromName("shield")->getChildren().getFirstElem()->getMaterial(0).setTexture(0, tex);

	if (m_behaviour) 
		m_behaviour->adjustStats(attributes);
}

bool CSpell::canStartCast()
{
	return m_state == SS_Ready;
}

bool CSpell::isCasting()
{
	return m_state == SS_Casting;
}

void CSpell::startCast(CTouchElement* touch)
{
	m_touch = touch;
	setState(SS_Casting);
	CGesture::GetInstance()->Reset();
}

void CSpell::update(f32 time)
{
	CWeaponObject::update(time);

	m_fadeAlpha -= time;
	switch (m_state)
	{
	case SS_Disabled:
		break;

	case SS_Ready:
		break;

	case SS_Casting:
		{
			p2i p;
			m_touch->GetTouchPos_Current(p.X, p.Y);
			if (m_touch->IsActive() && CGesture::GetInstance()->GetInput().size() < 100)
			{
				CGesture::GetInstance()->Update(p, time);

				m_fadeAlpha = 1.0f;
				m_gesture.set_used(0);
				const CGesture::TKeys& input = CGesture::GetInstance()->GetInput();
				for (int i = 0; i < input.size(); ++i)
				{
					m_gesture.push_back(v3f(input[i].Point.X, input[i].Point.Y, 0.0f));
				}
			}
			else
			{
				if (CGesture::GetInstance()->MatchGesture() == m_level)
				{
					CPlayfield::GetInstance()->getChallenge()->specialWeaponUsed();
					m_behaviour->activate(p);
					setState(SS_Active);
				}
				else
				{
					setState(SS_Ready);
				}
			}
		}
		break;

	case SS_Active:
		if (!m_behaviour->update(time))
		{
			setState(SS_Cooldown);
		}
		break;

	case SS_Cooldown:
		{
			m_cooldown += time;
			if (m_cooldown >= m_stat_cooldown)
			{
				m_cooldown = 0;
				setState(SS_Ready);
			}
		}
		break;
	}

	m_shield.updateAtEndOfFrame(time);
}

void CSpell::draw()
{
	//CGesture::GetInstance()->DebugDraw();

	drawGesture();

	if (m_state == SS_Active) m_behaviour->draw2D();
}

void CSpell::draw3D()
{
	if (m_state == SS_Active) m_behaviour->draw3D();
}

void CSpell::setVisible(bool visible)
{
	m_visible = visible;
	m_Node->setVisible(m_visible && m_level != ST_None);
}

bool CSpell::isVisible()
{
	return m_visible;
}

void CSpell::setState(ESpellState state)
{
	m_state = state;

	switch (m_state)
	{
	case SS_Disabled:
		break;

	case SS_Ready:
		os::Timer::setSpeed(1.0f);
		m_shield.setAnim("spell_off");
		break;

	case SS_Casting:
		os::Timer::setSpeed(0.5f);
		m_shield.setAnim("spell_on");
		break;

	case SS_Active:
		os::Timer::setSpeed(1.0f);
		m_shield.setAnim("cooldown");
		break;

	case SS_Cooldown:
		m_shield.setAnim("cooldown");
		break;
	}
}

float CSpell::getCooldown()
{
	if (m_state != SS_Cooldown)
		return 0.0f;

	return max(0.0f, 1.0f - m_cooldown / m_stat_cooldown);
}

ESpellState CSpell::getState()
{
	return m_state;
}

void CSpell::setShopState()
{
	m_shield.setAnim("spell_off");
}

void CSpell::drawGesture ()
{
	if (m_fadeAlpha > 0.0f && m_gesture.size() > 3)
	{
		int size = m_gesture.size() - 1;

		/*
		m_vertices.set_used(0);
		m_indices.set_used(0);

		SColor color = 0x7fffffff;
		color.A = 127 * m_fadeAlpha;

		for (int i = 0; i < size; ++i)
		{
			int k = MAX(i - 1, 0);
			v2f p0 = v2f(m_gesture[k].X, m_gesture[k].Y);
			v2f p1 = v2f(m_gesture[i + 0].X, m_gesture[i + 0].Y);
			v2f p2 = v2f(m_gesture[i + 1].X, m_gesture[i + 1].Y);
			k = MIN(i + 2, size);
			v2f p3 = v2f(m_gesture[k].X, m_gesture[k].Y);
			v2f m1 = 0.5f * (p2 - p0);
			v2f m2 = 0.5f * (p3 - p1);

			int steps = MAX((int)((p2 - p1).getLength() / 5), 1);
			for (int j = 0; j < steps; ++j)
			{
				float t1 = float(j + 0) / steps;
				float halfWidth = 10.0f;
				float offset = 0.0f;

				v2f lp;
				lp = HermiteInterpolationOffset(t1, offset + halfWidth, p1, p2, m1, m2);
				m_vertices.push_back(S3DVertex(v3f(lp.X, lp.Y, 0.0f), v3f(), color, v2f(0.0f, 0.0f)));
				lp = HermiteInterpolationOffset(t1, offset - halfWidth, p1, p2, m1, m2);
				m_vertices.push_back(S3DVertex(v3f(lp.X, lp.Y, 0.0f), v3f(), color, v2f(0.0f, 1.0f)));
				if (i > 0 || j > 0)
				{
					m_indices.push_back(m_vertices.size() - 4);
					m_indices.push_back(m_vertices.size() - 3);
					m_indices.push_back(m_vertices.size() - 2);
					m_indices.push_back(m_vertices.size() - 3);
					m_indices.push_back(m_vertices.size() - 2);
					m_indices.push_back(m_vertices.size() - 1);
				}
			}
		}

		__IRR_DRIVER()->set2DTexture(m_fingerTrailTexture, true);
		__IRR_DRIVER()->set2DUseVertexAlpha(true);
		__IRR_DRIVER()->drawVertexPrimitiveList(&m_vertices[0], &m_indices[0], 0, m_indices.size(), m_indices.size() / 3, EVT_STANDARD, EPT_TRIANGLES, EIT_16BIT);
		*/

		m_vertices.set_used(4 * size);
		m_indices.set_used(6 * size);

		SColor color = 0x7fffffff;
		color.A = 127 * m_fadeAlpha;
		float lineWidth = 32.0f;

		// indices
		for (int i = 0; i < size; ++i)
		{
			m_indices[6 * i + 0] = 4 * i + 0;
			m_indices[6 * i + 1] = 4 * i + 1;
			m_indices[6 * i + 2] = 4 * i + 2;
			m_indices[6 * i + 3] = 4 * i + 2;
			m_indices[6 * i + 4] = 4 * i + 1;
			m_indices[6 * i + 5] = 4 * i + 3;
		}

		for (int i = 0; i < size; ++i)
		{
			v3f p1 = m_gesture[i];
			v3f p2 = m_gesture[i + 1];
			v3f parr12 = p2 - p1;
			v3f perp12(-parr12.Y, parr12.X, 0.0f);
			v3f perp;

			// left
			if (i == 0)
			{
				perp = perp12;
			}
			else
			{
				v3f p0 = m_gesture[i - 1];
				v3f parr01 = p1 - p0;
				v3f perp01(-parr01.Y, parr01.X, 0.0f);
				perp = 0.5f * (perp01 + perp12);
			}
			perp *= 0.5f * lineWidth / perp.getLength();
			m_vertices[4 * i + 0] = S3DVertex(p1 + perp, v3f(), color, v2f(0.0f, 0.0f));
			m_vertices[4 * i + 1] = S3DVertex(p1 - perp, v3f(), color, v2f(0.0f, 1.0f));

			// right
			if (i == size - 1)
			{
				perp = perp12;
			}
			else
			{
				v3f p3 = m_gesture[i + 2];
				v3f parr23 = p3 - p2;
				v3f perp23(-parr23.Y, parr23.X, 0.0f);
				perp = 0.5f * (perp23 + perp12);
			}
			perp *= 0.5f * lineWidth / perp.getLength();
			m_vertices[4 * i + 2] = S3DVertex(p2 + perp, v3f(), color, v2f(1.0f, 0.0f));
			m_vertices[4 * i + 3] = S3DVertex(p2 - perp, v3f(), color, v2f(1.0f, 1.0f));
		}
		
		__IRR_DRIVER()->set2DTexture(m_fingerTrailTexture, true);
		__IRR_DRIVER()->set2DUseVertexAlpha(true);
		__IRR_DRIVER()->drawVertexPrimitiveList(&m_vertices[0], &m_indices[0], 0, size * 6, size * 2, EVT_STANDARD, EPT_TRIANGLES, EIT_16BIT);
	}
}

