CBoulderBehaviour::CBoulderBehaviour ()
{
	ISceneNode* node = LoadColladaScene("Scenes/Spells/boulder.bdae");
	cleanNode(node);
	__IRR_SCENE()->getRootSceneNode()->addChild(node);
	m_boulder.setRoot(node);
	m_boulder.getRoot()->setVisible(false);

	m_shadow = LoadColladaScene("Scenes/Goblin/shadow.bdae");
	cleanNode(m_shadow);
	__IRR_SCENE()->getRootSceneNode()->addChild(m_shadow);
	m_shadow->setVisible(false);

	m_soundIndex = -1;
}

CBoulderBehaviour::~CBoulderBehaviour ()
{
	m_boulder.getRoot()->remove();
	m_boulder.getRoot()->drop();
}

void CBoulderBehaviour::adjustStats (IAttributes* attr)
{
	m_radius = attr->getAttributeAsFloat("Radius");
	m_duration = attr->getAttributeAsFloat("Duration");
}

void CBoulderBehaviour::activate (p2i gestureEnd)
{
	CPlayfield * playfield = CPlayfield::GetInstance();

	v3f pos = playfield->getPath().start + playfield->getPath().getVector() * 0.9f;
	pos += v3f(0, 30, 0);
	m_boulder.getRoot()->setPosition(pos);

	m_boulder.setAnim("roll");
	m_boulder.getRoot()->getSceneNodeFromName("boulder")->setVisible(true);
	m_boulder.getRoot()->getSceneNodeFromName("break")->setVisible(false);
	m_boulder.getRoot()->setVisible(true);
	m_shadow->setVisible(true);

	m_falling = true;
	m_breaking = false;

	m_time = 0;
	m_speed = 0;
	m_acceleration = 0;

	m_soundIndex = -1;
}

bool CBoulderBehaviour::update (f32 time)
{
	CPlayfield * playfield = CPlayfield::GetInstance();
	m_time += time;
	bool spellDone = false;

	const f32 damage_radius = m_radius * 1.3f;
	const f32 boulder_scale = (m_radius / 0.75f);
	const f32 shadow_scale = boulder_scale * 3.5f;

	const f32 max_speed = 5.0f;
	const f32 max_acceleration = 10.0f;
	const f32 fadeTime = 0.3f;

	plane3df ground = CPlayfield::GetInstance()->getGroundPlane();
	ground.D -= m_radius;
	plane3df castle = CPlayfield::GetInstance()->getCastlePlane();
	castle.D -= m_radius;

	v3f pos = m_boulder.getRoot()->getPosition();

	if (!m_breaking)
	{
		/// Falling 
		if (m_falling)
		{
			pos += v3f(0, -50, 0) * time;
			
			bool falling = (ground.classifyPointRelation(pos) == ISREL3D_FRONT);

			if (!falling)
			{
				ground.getIntersectionWithLine(pos, vector3df(0, 1, 0), pos);
				m_falling = false;
				playfield->SetCameraShake(0.7f, 1.0f);
				m_acceleration = -max_acceleration;

				__MGR_SOUNDS()->play( SFX_SPELL_FALLING_BOULDER_IMPACT );
			}
		}

		/// Killing Units
		if (!m_falling)
		{
			int unitsHitByKind[UK_Unknown + 1] = { 0 };
			// kill units in area
			const TUnitList& units = CPlayfield::GetInstance()->getUnits();
			for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
			{
				CUnit* unit = *it;
				if ((unit->getAbsolutePosition() - (pos - v3f(0,m_radius,0))).getLength() < damage_radius)
				{
					if (unit->isPetrified())
						unit->unpetrify(true);
					else if (unit->canBeKilledByLightning())
					{
						unit->damageUnit(9999, UDS_Lightning);
						++unitsHitByKind[unit->getUnitKind()];
					}
				}
			}
			CPlayfield::GetInstance()->getChallenge()->unitsWereKilledByWeapon(UDS_Lightning, unitsHitByKind);
		}

		/// Acceleration		
		f32 acceleration = 0.0f;
		if (!m_falling)
		{
			f32 angle = (__APP()->GetAccelerometer()->getPitch() - PI/2);
			
			if ( __IRR_DRIVER()->getOrientation3D() == EOO_90 )
				angle*=-1;

			if (fabs(angle) >= PI / 18)
			{
				m_acceleration = max_acceleration * angle / (PI/6);
				CLAMP(m_acceleration, -max_acceleration, max_acceleration);
			}
		}
		m_speed += m_acceleration * time;
		CLAMP(m_speed, -max_speed, max_speed);

		if(m_speed != 0.0 && (m_soundIndex == -1 || !__MGR_SOUNDS()->isSoundPlaying( SFX_SPELL_ROLLING_BOULDER, m_soundIndex)))
			m_soundIndex = __MGR_SOUNDS()->play( SFX_SPELL_ROLLING_BOULDER, true );

		/// Move Boulder
		f32 distance = m_speed * time;
		pos = pos + playfield->getPath().getVector().normalize() * distance;
		if (castle.classifyPointRelation(pos) != ISREL3D_FRONT)
		{
			castle.getIntersectionWithLine(pos, playfield->getPath().getVector(), pos);
			m_speed = -m_speed;
		}

		m_boulder.getRoot()->setPosition(pos);
		
		/// Scale Boulder
		m_boulder.getRoot()->setScale(v3f(1,1,1) * boulder_scale);

		/// Shadow
		v3f shadowPos;
		playfield->getGroundPlane().getIntersectionWithLine(pos, v3f(0,1,0), shadowPos);
		m_shadow->setPosition(shadowPos);
		float distanceFromGround = playfield->getGroundPlane().getDistanceTo(pos);
		float scale = shadow_scale - 0.2f * distanceFromGround;
		CLAMP(scale, 0.4f, shadow_scale);
		m_shadow->setScale(v3f(1,1,1) * scale);

		/// Break;
		if (m_time > m_duration)
		{
			m_breaking = true;
			m_boulder.setAnim("break", false);
			m_boulder.getRoot()->getSceneNodeFromName("boulder")->setVisible(false);
			m_boulder.getRoot()->getSceneNodeFromName("break")->setVisible(true);
			m_boulder.getRoot()->setRotation( v3f(0, RandFloat(0,2*PI), 0) );
		}

		/// Dissapear
		if (playfield->getPath().start.X > pos.X)
		{
			spellDone = true;
		}
	}
	else
	{
		if (m_boulder.checkEvent("anim_end"))
		{
			spellDone = true;
		}

		if(m_soundIndex != -1)
		{
			__MGR_SOUNDS()->stop( SFX_SPELL_ROLLING_BOULDER, m_soundIndex, 500 );
			m_soundIndex = -1;
		}
	}

	if (spellDone)
	{
		m_boulder.getRoot()->setVisible(false);
		m_shadow->setVisible(false);
		
		if(m_soundIndex != -1)
		{
			__MGR_SOUNDS()->stop( SFX_SPELL_ROLLING_BOULDER, m_soundIndex, 500 );
			m_soundIndex = -1;
		}

		return false;
	}

	if (!m_breaking)
	{
		f32 p = 2 * PI * m_radius;
		f32 rot = 2 * PI * pos.X / p;
		m_boulder.getRoot()->setRotation( v3f(0,0,rot) );
	}

	m_boulder.updateAtEndOfFrame(time);

	return true;
}

