CLightningBehaviour::CLightningBehaviour ()
{
	ASprite* spr = new ASprite;
	spr->Load("Ingame/lightning");
	m_sprite.SetASprite(spr);

	ISceneNode* wave = LoadColladaScene("Scenes/Spells/strike_plane.bdae");
	cleanNode(wave);
	__IRR_SCENE()->getRootSceneNode()->addChild(wave);
	wave->setVisible(false);
	m_wave.setRoot(wave);
}

CLightningBehaviour::~CLightningBehaviour ()
{
	delete m_sprite.GetASprite();

	m_wave.getRoot()->drop();
	m_wave.getRoot()->remove();
}

v3f ProjectPointOnTheGround (p2i point2d)
{
	line3df ray = __IRR_SCENE()->getSceneCollisionManager()->getRayFromScreenCoordinates(point2d);
	plane3df flying, ground, castle;
	flying = CPlayfield::GetInstance()->getFlyingPlane();
	ground = CPlayfield::GetInstance()->getGroundPlane();
	castle = CPlayfield::GetInstance()->getCastlePlane();
	v3f v;
	flying.getIntersectionWithLine(ray.start, ray.getVector(), v);
	ground.getIntersectionWithLine(v, v3f(0, 1, 0), v);
	if (castle.classifyPointRelation(v) == ISREL3D_BACK)
		castle.getIntersectionWithLine(v, castle.Normal, v);
	
	return v;
}

void CLightningBehaviour::activate (p2i gestureEnd)
{
	v3f v = ProjectPointOnTheGround(gestureEnd);
	p2i p = screenFrom3DPos(v);

	m_wave.getRoot()->setPosition(v + v3f(0, 0.1, 0));
	m_wave.getRoot()->setVisible(true);
	m_wave.setAnim(0, false);

	// start the animation
	m_sprite.SetAnim(0, 0);
	m_sprite.SetPosition(p.X, p.Y);

	// kill units in area
	int unitsHitByKind[UK_Unknown + 1] = { 0 };
	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
	{
		CUnit* unit = *it;
		if ((unit->getAbsolutePosition() - v).getLength() < 4.0f)
		{
			if (unit->isPetrified())
				unit->unpetrify(true);
			else if (unit->canBeKilledByLightning())
			{
				unit->damageUnit(9999, UDS_Lightning);
				++unitsHitByKind[unit->getUnitKind()];
			}
		}
	}
	CPlayfield::GetInstance()->getChallenge()->unitsWereKilledByWeapon(UDS_Lightning, unitsHitByKind);

	__MGR_SOUNDS()->play( SFX_SPELL_LIGHTNING );
}

bool CLightningBehaviour::update (f32 time)
{
	bool continueSpell = true;

	if (m_wave.checkEvent("anim_end"))
	{
		m_wave.getRoot()->setVisible(false);
		continueSpell = false;
	}

	m_sprite.Update(time);
	m_wave.updateAtEndOfFrame(time);

	return continueSpell;
}

void CLightningBehaviour::draw2D ()
{
	m_sprite.Draw();
}

void CLightningBehaviour::adjustStats (IAttributes* attr)
{
	//m_radius = attr->getAttributeAsFloat("Radius");
}

CTornadoBehaviour::CTornadoBehaviour ()
{
	m_touch.SetEnabled(false);
	m_touch.m_zLevel = 0; // on top

	ISceneNode* tornado = LoadColladaScene("Scenes/Tornado/tornado.bdae");
	cleanNode(tornado);
	tornado->getSceneNodeFromName("tornato")->getChildren().getFirstElem()->getMaterial(0).setMaterialType(EMT_TRANSPARENT_TEXTURE_VERTEX_ALPHA);
	tornado->getSceneNodeFromName("tornato")->getChildren().getFirstElem()->getMaterial(0).setFlag(EMF_LIGHTING, false);
	tornado->setScale(0.20f * v3f(1.4f, 1.0f, 1.4f));
	__IRR_SCENE()->getRootSceneNode()->addChild(tornado);
	tornado->setVisible(false);
	m_tornado.setRoot(tornado);

	m_bottom = m_tornado.getRoot()->getSceneNodeFromName("Point01");

	m_dust = 0;
	m_soundIndex = -1;
}

CTornadoBehaviour::~CTornadoBehaviour ()
{
	m_tornado.getRoot()->drop();
	m_tornado.getRoot()->remove();

	if (m_dust)
	{
		RemoveParticleSystem(m_dust);
		m_dust = 0;
	}
}

void CTornadoBehaviour::activate (p2i gestureEnd)
{
	v3f v = ProjectPointOnTheGround(gestureEnd);
	p2i p = screenFrom3DPos(v);

	m_tornado.getRoot()->setPosition(v);
	m_tornado.getRoot()->setVisible(true);
	m_tornado.setAnimAnim("tornado_down", "tornado_loop");

	m_touch.SetEnabled(true);

	m_time = 0;

	m_soundIndex = -1;
}

bool CTornadoBehaviour::update (f32 time)
{
	m_time += time;
	bool continueSpell = m_time < m_maxTime;

	v3f pos3D = m_tornado.getRoot()->getPosition();
	p2i pos2D = screenFrom3DPos(pos3D);
	m_touch.SetScreenCoordinates(pos2D.X - 40, 0, 80, 320);

	if (m_tornado.checkEvent("on_ground"))
	{
		m_dust = AddParticleSystem("tornado_dust");
		m_dust->SetScale(0.07f);
		m_dust->SetRotation(quaternion(0, 0.5f * PI, 0.0f) * quaternion(0.5f * PI, 0.0f, 0.0f));
	}

	v3f target = pos3D;
	f32 angle = (__APP()->GetAccelerometer()->getPitch() - PI/2);
	line3df path = CPlayfield::GetInstance()->getPath();
	
	//patch for the accelerometer when in opposite direction
	if ( __IRR_DRIVER()->getOrientation3D() == EOO_90 )
	{
		angle*=-1;
	}

#ifdef OS_IPHONE	
	if (angle >  PI/18.0f) target = path.end;
	if (angle < -PI/18.0f) target = path.start;
#endif
	if (m_touch.IsActive())
	{
		p2i p;
		m_touch.GetTouchPos_Current(p.X, p.Y);
		target = ProjectPointOnTheGround(p);
	}
	v3f velocity = (target - pos3D) / time;
	if (velocity.getLength() > m_speed)
		velocity.setLength(m_speed);
	pos3D += velocity * time;
	m_tornado.getRoot()->setPosition(pos3D);

	ICameraSceneNode* cam = __IRR_SCENE()->getActiveCamera();
	v3f dir = cam->getAbsolutePosition() - m_tornado.getRoot()->getPosition();
	dir.Y = 0;
	m_tornado.getRoot()->setRotation(quaternion().rotationFromTo(dir, v3f(0, 0, 1)));

	if (m_dust)
	{
		v3f p1 = m_bottom->getAbsolutePosition();
		v3f dir = p1 - cam->getAbsolutePosition();
		dir.setLength(2.0f);
		m_dust->SetPosition(p1 - dir);
	}

	if (!continueSpell)
	{
		m_tornado.setAnim("tornado_up", false);
		m_touch.SetEnabled(false);

		if (m_dust)
		{
			RemoveParticleSystem(m_dust);
			m_dust = 0;

			if(m_soundIndex != -1)
			{
				__MGR_SOUNDS()->stop( SFX_SPELL_TORNADO, m_soundIndex, 500 );
				m_soundIndex = -1;
			}
		}
	}

	int unitsHitByKind[UK_Unknown + 1] = { 0 };
	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
	{
		affectUnit(time, *it, continueSpell, unitsHitByKind);
	}
	const array<CBomb*>& bombs = CPlayfield::GetInstance()->getBombs();
	for (int i = 0; i < bombs.size(); ++i)
		affectBomb(time, bombs[i], continueSpell);
	CPlayfield::GetInstance()->getChallenge()->unitsWereKilledByWeapon(UDS_Lightning, unitsHitByKind);	

	m_tornado.updateAtEndOfFrame(time);

	if(continueSpell && (m_soundIndex == -1 || !__MGR_SOUNDS()->isSoundPlaying( SFX_SPELL_TORNADO, m_soundIndex)))
		m_soundIndex = __MGR_SOUNDS()->play( SFX_SPELL_TORNADO );

	return continueSpell;
}

void CTornadoBehaviour::affectUnit (f32 time, CUnit* unit, bool continueSpell, int* unitsHitByKind)
{
	v3f unitPos = unit->getAbsolutePosition();
	v3f myPos = m_tornado.getRoot()->getPosition();
	v3f direction = unitPos - myPos;
	direction.Y = 0.0f;
	if (unit->getState() == US_Tornado)
	{
		float height = 3.5f + 0.4f * unit->m_lane;
		direction.rotateXZBy(-15);
		direction.Y = 0.0f;
		direction.setLength(1.5f);

		v3f target = myPos + v3f(0, height, 0) + direction;
		v3f velocityXZ = (target - unitPos) / time; velocityXZ.Y = 0;
		v3f velocityY  = (target - unitPos) / time; velocityY.X = velocityY.Z = 0;
		float distanceY = target.Y - unitPos.Y;
		if (velocityXZ.getLength() > 25.0f - 2.5f * distanceY)
			velocityXZ.setLength(25.0f - 2.5f * distanceY);
		if (velocityY.getLength() > 1.5f)
			velocityY.setLength(1.5f);

		unitPos += (velocityXZ + velocityY) * time;
		unit->setMPosition(unitPos);
		unit->setVelocity(velocityXZ + velocityY);

		if (fabsf(distanceY) < 0.4f || !continueSpell)
		{
			unit->damageUnit(9999, UDS_Tornado);
			unit->setState(US_Falling);
			++unitsHitByKind[unit->getUnitKind()];
		}
	}
	else
	{
		if (direction.getLength() < m_radius && unit->canBeTakenByTornado())
		{
			unit->setState(US_Tornado);
		}
	}
}

void CTornadoBehaviour::affectBomb (f32 time, CBomb* bomb, bool continueSpell)
{
	v3f bombPos = bomb->getRoot()->getAbsolutePosition();
	v3f myPos = m_tornado.getRoot()->getPosition();
	v3f direction = bombPos - myPos;
	direction.Y = 0.0f;
	if (bomb->isFree() && direction.getLength() < m_radius)
	{
		float height = 3.5f;
		direction.rotateXZBy(-15);
		direction.Y = 0.0f;
		direction.setLength(1.5f);

		v3f target = myPos + v3f(0, height, 0) + direction;
		v3f velocityXZ = (target - bombPos) / time; velocityXZ.Y = 0;
		v3f velocityY  = (target - bombPos) / time; velocityY.X = velocityY.Z = 0;
		float distanceY = target.Y - bombPos.Y;
		if (velocityXZ.getLength() > 25.0f - 2.5f * distanceY)
			velocityXZ.setLength(25.0f - 2.5f * distanceY);
		if (velocityY.getLength() > 1.5f)
			velocityY.setLength(1.5f);

		bombPos += (velocityXZ + velocityY) * time;
		bomb->getRoot()->setPosition(bombPos);
		bomb->setVelocity(velocityXZ + velocityY);
	}
}

void CTornadoBehaviour::adjustStats (IAttributes* attr)
{
	m_speed = attr->getAttributeAsFloat("Speed");
	m_radius = attr->getAttributeAsFloat("Radius");
	m_maxTime = attr->getAttributeAsFloat("Time");
}

CGhostArmyBehaviour::CGhostArmyBehaviour ()
{
	ASprite* spr = new ASprite;
	spr->Load("Ingame/ghost_army");
	for (int i = 0; i < k_ghosts; ++i)
		m_sprites[i].SetASprite(spr);

	m_soundIndex = -1;
}

CGhostArmyBehaviour::~CGhostArmyBehaviour ()
{
	delete m_sprites[0].GetASprite();
}

bool CompareZ (v3f a, v3f b)
{
	return a.Z < b.Z;
}

void GetSortedIndices(const float * arr, int len, int * result);
void CGhostArmyBehaviour::activate (p2i gestureEnd)
{
	float zs[k_ghosts];
	int indices[k_ghosts];
	v3f poss[k_ghosts];
	for (int i = 0; i < k_ghosts; ++i)
	{
		m_velocities[i] = CPlayfield::GetInstance()->getPath().getVector().setLength(-RandFloat(4.5f, 5.5f));
		poss[i] = CPlayfield::GetInstance()->getPath().end +
			v3f(2.4f + RandFloat(-2.3f, 2.3f), 0.2f, RandFloat(-1.3f, 1.3f));
		zs[i] = poss[i].Z;
		m_sprites[i].SetAnim(0);
	}
	GetSortedIndices(zs, k_ghosts, indices);
	for (int i = 0; i < k_ghosts; ++i)
	{
		m_positions[k_ghosts - i - 1] = poss[indices[i]];
	}
	m_kills = 0;

	m_soundIndex = -1;
}

bool CGhostArmyBehaviour::update (f32 time)
{
	v3f pos;
	for (int i = 0; i < k_ghosts; ++i)
		pos += m_positions[i];
	pos /= k_ghosts;

	line3df path = CPlayfield::GetInstance()->getPath();
	bool continueSpell = path.getVector().dotProduct(pos - path.start) >= 0.0f;

	for (int i = 0; i < k_ghosts; ++i)
		m_positions[i] += m_velocities[i] * time;

	// check for kill
	int unitsHitByKind[UK_Unknown + 1] = { 0 };
	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
	{
		CUnit* unit = *it;
		v3f dir = unit->getAbsolutePosition() - pos;
		dir.Z = 0.0f;
		if (unit->canBeKilledByGhostArmy() && dir.getLength() < m_radius)
		{
			if (unit->isPetrified())
				unit->unpetrify(true);
			else
				unit->damageUnit(9999, UDS_GhostArmy);
			if (unit->getSouls() > 0)
			{
				++m_kills;
				CPlayfield::GetInstance()->addSouls(unit->getSouls() * (m_kills % 2), unit->getChestDummy()->getAbsolutePosition());
			}
			++unitsHitByKind[unit->getUnitKind()];
		}
	}
	CPlayfield::GetInstance()->getChallenge()->unitsWereKilledByWeapon(UDS_Lightning, unitsHitByKind);

	for (int i = 0; i < k_ghosts; ++i)
		m_sprites[i].Update(time * (0.95f + 0.05f * i));

	if(continueSpell)
	{
		if(m_soundIndex == -1 || !__MGR_SOUNDS()->isSoundPlaying( SFX_SPELL_RUNNING_GHOSTS, m_soundIndex))
			m_soundIndex = __MGR_SOUNDS()->play( SFX_SPELL_RUNNING_GHOSTS );
	}
	else
	{
		if(m_soundIndex != -1)
		{
			__MGR_SOUNDS()->stop( SFX_SPELL_RUNNING_GHOSTS, m_soundIndex, 500);
			m_soundIndex = -1;
		}
	}

	return continueSpell;
}

void CGhostArmyBehaviour::draw3D ()
{
	for (int i = 0; i < k_ghosts; ++i)
		m_sprites[0].Draw3D(m_positions[i], 1.2f);
}

void CGhostArmyBehaviour::adjustStats (IAttributes* attr)
{
	m_radius = 1.5f;
}

CEarthquakeBehaviour::CEarthquakeBehaviour ()
{
}

CEarthquakeBehaviour::~CEarthquakeBehaviour ()
{
}

void CEarthquakeBehaviour::activate (p2i gestureEnd)
{
	m_time = 0.0f;
}

bool CEarthquakeBehaviour::update (f32 time)
{
	bool continueSpell = m_time < m_maxTime;
	float t = m_time / m_maxTime;
	t = 0.8f * powf(1.0f - t, 10.0f) + 0.2f;
	m_time += time;

	CPlayfield::GetInstance()->SetCameraShake(1.0f, t * m_power);

	const TUnitList& units = CPlayfield::GetInstance()->getUnits();
	for (TUnitList::ConstIterator it = units.begin(); it != units.end(); it++)
	{
		CUnit* unit = *it;
		if (unit->canBeStunnedByEarthquake())
		{
			if (unit->isPetrified())
				unit->unpetrify(true);
			unit->freeAllSlavesFromMindControl();
			unit->setState(US_Earthquake);
		}
		if (unit->getState() == US_Earthquake)
		{
			line3df path = CPlayfield::GetInstance()->getPath();
			v3f pos = unit->getPosition();

			float angle = RandFloat(-5, +5);
			v3f dir = v3f(0, 0, +RandFloat(0.8, 1.2));
			dir.rotateXZBy(angle);
			unit->setMPosition(pos + dir * time);

			if (pos.Z - path.end.Z > 1.8f)
			{
				unit->throwUnitInWater(pos + v3f(0, -2, +1.5f), 0.5f);
			}
		}
		if (!continueSpell && unit->getState() == US_Earthquake)
		{
			unit->setState(US_Walking);
		}
	}

	return continueSpell;
}

void CEarthquakeBehaviour::adjustStats (IAttributes* attr)
{
	m_maxTime = attr->getAttributeAsFloat("Time");
	m_power = attr->getAttributeAsFloat("ShakePower");
}
